#!/usr/bin/env python3
"""Acceptance test: leaderboard service (https://cswork.org/projects/leaderboard).

Start your service, then run:
    BASE_URL=http://127.0.0.1:8080 python3 accept_test.py
Standard library only. Each check uses a fresh board with a random name, so reruns against the
same server are fine. Exit code 0 means every check passed.
"""
import json
import os
import random
import string
import sys
import threading
import urllib.error
import urllib.request

BASE = os.environ.get('BASE_URL', 'http://127.0.0.1:8080').rstrip('/')


def call(method, path, body=None, raw=None):
    data = raw if raw is not None else (None if body is None else json.dumps(body).encode())
    req = urllib.request.Request(BASE + path, data=data, method=method, headers={'Content-Type': 'application/json'})
    try:
        with urllib.request.urlopen(req, timeout=5) as r:
            status, text = r.status, r.read()
    except urllib.error.HTTPError as e:
        status, text = e.code, e.read()
    return status, (json.loads(text) if text.strip() else None)


def fresh():
    return 'b' + ''.join(random.choices(string.ascii_lowercase + string.digits, k=10))


def submit(board, player, score):
    status, body = call('POST', f'/boards/{board}/scores', {'player': player, 'score': score})
    assert status == 200, f'submitting {player}={score} answered {status}'
    return body


def expected(best):
    """The board as the brief defines it: score high to low, ties by name; rank = 1 + strictly higher scores."""
    order = sorted(best.items(), key=lambda kv: (-kv[1], kv[0]))
    return [{'player': p, 'score': s, 'rank': 1 + sum(1 for v in best.values() if v > s)} for p, s in order]


CHECKS = []


def check(fn):
    CHECKS.append(fn)
    return fn


@check
def submits_and_reads():
    """POST a score, then GET the player with their score and rank"""
    b = fresh()
    assert submit(b, 'ada', 50) == {'player': 'ada', 'score': 50, 'rank': 1}
    submit(b, 'bob', 70)
    assert call('GET', f'/boards/{b}/players/ada') == (200, {'player': 'ada', 'score': 50, 'rank': 2})


@check
def keeps_the_best_score():
    """a lower score never replaces a player's best"""
    b = fresh()
    submit(b, 'ada', 90)
    assert submit(b, 'ada', 40)['score'] == 90
    assert submit(b, 'ada', 95)['score'] == 95


@check
def rejects_bad_input():
    """400 for a missing player, a bad name, a negative, fractional or string score, or non-JSON"""
    b = fresh()
    for body in ({'score': 1}, {'player': 'a b', 'score': 1}, {'player': 'x' * 33, 'score': 1},
                 {'player': 'ada', 'score': -1}, {'player': 'ada', 'score': 1.5}, {'player': 'ada', 'score': '7'}):
        status, _ = call('POST', f'/boards/{b}/scores', body)
        assert status == 400, f'{body} answered {status}'
    assert call('POST', f'/boards/{b}/scores', raw=b'nope')[0] == 400
    assert call('GET', f'/boards/{b}/top?limit=0')[0] == 400
    assert call('GET', f'/boards/{b}/top?limit=101')[0] == 400


@check
def ties_share_a_rank():
    """ties order by name and share a rank; the next rank skips (1, 2, 2, 4)"""
    b = fresh()
    for player, score in (('cat', 80), ('bob', 80), ('ada', 100), ('dan', 10)):
        submit(b, player, score)
    status, body = call('GET', f'/boards/{b}/top')
    assert status == 200 and body['total'] == 4, (status, body)
    assert [(e['player'], e['rank']) for e in body['items']] == [('ada', 1), ('bob', 2), ('cat', 2), ('dan', 4)], body


@check
def pages_the_top_list():
    """top?limit=&offset= pages through the whole board"""
    b = fresh()
    best = {f'p{i:02d}': (i * 37) % 23 for i in range(30)}
    for p, s in best.items():
        submit(b, p, s)
    want = expected(best)
    got = []
    for offset in range(0, 30, 7):
        status, body = call('GET', f'/boards/{b}/top?limit=7&offset={offset}')
        assert status == 200 and body['total'] == 30, (status, body)
        got += body['items']
    assert got == want, 'pages do not add up to the whole board in order'
    assert call('GET', f'/boards/{b}/top?offset=40')[1]['items'] == []


@check
def neighbours_around_a_player():
    """players/<p>/around?radius=r lists r places either side, clipped at the ends"""
    b = fresh()
    best = {f'p{i}': 100 - i for i in range(8)}
    for p, s in best.items():
        submit(b, p, s)
    status, body = call('GET', f'/boards/{b}/players/p4/around?radius=2')
    assert status == 200 and [e['player'] for e in body['items']] == ['p2', 'p3', 'p4', 'p5', 'p6'], body
    assert [e['player'] for e in call('GET', f'/boards/{b}/players/p0/around?radius=2')[1]['items']] == ['p0', 'p1', 'p2']
    assert [e['player'] for e in call('GET', f'/boards/{b}/players/p7/around?radius=1')[1]['items']] == ['p6', 'p7']


@check
def unknown_and_deleted_players():
    """unknown players are 404; deleting one moves the ranks below it up"""
    b = fresh()
    submit(b, 'ada', 3)
    submit(b, 'bob', 2)
    assert call('GET', f'/boards/{b}/players/zed')[0] == 404
    assert call('DELETE', f'/boards/{b}/players/ada')[0] in (200, 204)
    assert call('GET', f'/boards/{b}/players/ada')[0] == 404
    assert call('GET', f'/boards/{b}/players/bob')[1]['rank'] == 1


@check
def matches_a_model_on_random_data():
    """600 random submissions: every rank and the whole order match a brute-force model"""
    b = fresh()
    rng = random.Random(7)
    best = {}
    for _ in range(600):
        p, s = f'u{rng.randrange(150)}', rng.randrange(60)
        submit(b, p, s)
        best[p] = max(best.get(p, -1), s)
    want = expected(best)
    got = []
    for offset in range(0, len(want), 100):
        got += call('GET', f'/boards/{b}/top?limit=100&offset={offset}')[1]['items']
    assert got == want, 'the order or ranks differ from the model'
    for e in rng.sample(want, 20):
        assert call('GET', f'/boards/{b}/players/{e["player"]}')[1] == e, e


@check
def concurrent_submissions_keep_the_max():
    """40 concurrent submissions for one player: the best one wins, nothing is lost"""
    b = fresh()
    scores = random.sample(range(1000), 40)
    gate = threading.Barrier(40)

    def hit(s):
        gate.wait()
        submit(b, 'ada', s)
        submit(b, f'q{s}', s)

    threads = [threading.Thread(target=hit, args=(s,)) for s in scores]
    for t in threads:
        t.start()
    for t in threads:
        t.join()
    assert call('GET', f'/boards/{b}/players/ada')[1]['score'] == max(scores)
    assert call('GET', f'/boards/{b}/top')[1]['total'] == 41


def main():
    failed = 0
    for fn in CHECKS:
        try:
            fn()
            print(f'PASS  {fn.__doc__}')
        except Exception as e:  # an assertion, or the service not answering
            failed += 1
            print(f'FAIL  {fn.__doc__}\n      {type(e).__name__}: {e}')
    print(f'\n{len(CHECKS) - failed}/{len(CHECKS)} checks passed')
    sys.exit(1 if failed else 0)


if __name__ == '__main__':
    main()

#!/usr/bin/env python3
"""Acceptance test: polite web crawler (https://cswork.org/projects/polite-crawler).

Tell it how to start your crawler, then run:
    CMD="python3 crawler.py" python3 accept_test.py
It starts two small local web sites, runs `$CMD <start url> --max-pages N --delay-ms D`, and checks
what your crawler printed and every request the sites received. Standard library only. Exit code
0 means every check passed.
"""
import json
import os
import shlex
import subprocess
import sys
import threading
import time
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer

CMD = shlex.split(os.environ.get('CMD', ''))
DELAY_MS = 150
ROBOTS = """User-agent: *
Disallow: /

User-agent: cswork-bot
Allow: /secret/public
Disallow: /secret
"""


def html(*links):
    return '<!doctype html><title>t</title><body>' + ''.join(f'<p><a href="{h}">link</a></p>' for h in links)


class Site:
    """A local site that records every request: (monotonic time, path, user agent)."""

    def __init__(self, pages):
        self.pages, self.requests, self.busy = pages, [], 0
        site = self

        class Handler(BaseHTTPRequestHandler):
            def do_GET(self):
                site.requests.append((time.monotonic(), self.path, self.headers.get('User-Agent') or ''))
                if self.path == '/busy':
                    site.busy += 1
                    if site.busy == 1:
                        return self.send(429, 'text/plain', 'slow down', {'Retry-After': '1'})
                page = site.pages.get(self.path)
                if page is None:
                    return self.send(404, 'text/plain', 'not found')
                self.send(200, *page)

            def send(self, status, kind, body, headers=None):
                data = body.encode()
                self.send_response(status)
                self.send_header('Content-Type', kind)
                for k, v in (headers or {}).items():
                    self.send_header(k, v)
                self.send_header('Content-Length', str(len(data)))
                self.end_headers()
                self.wfile.write(data)

            def log_message(self, *args):
                pass

        self.server = ThreadingHTTPServer(('127.0.0.1', 0), Handler)
        self.url = f'http://127.0.0.1:{self.server.server_address[1]}'
        threading.Thread(target=self.server.serve_forever, daemon=True).start()


OTHER = Site({'/ext': ('text/html', html('/'))})
SITE = Site({
    '/robots.txt': ('text/plain', ROBOTS),
    '/': ('text/html', html('/a', '/b', '/a#top', '/private/x', '/secret/hidden', '/secret/public/ok',
                            f'{OTHER.url}/ext', 'mailto:team@example.com', 'javascript:void(0)', '/data.json',
                            '/busy', '/missing', '?q=1')),
    '/a': ('text/html', html('b', '/c', '/', '#again')),
    '/b': ('text/html', html('/a', '/c?page=2')),
    '/c': ('text/html', html('d')),
    '/c?page=2': ('text/html', html('/c')),
    '/d': ('text/html', html('/e')),
    '/e': ('text/html', html()),
    '/?q=1': ('text/html', html('/')),
    '/private/x': ('text/html', html()),
    '/secret/public/ok': ('text/html', html()),
    '/secret/hidden': ('text/html', html('/never')),
    '/data.json': ('application/json', '{"note": "<a href=\\"/trap\\">not a link</a>"}'),
    '/busy': ('text/html', html('/f')),
    '/f': ('text/html', html()),
})
EXPECTED = {'/': 200, '/a': 200, '/b': 200, '/private/x': 200, '/secret/public/ok': 200, '/data.json': 200, '/busy': 200,
            '/missing': 404, '/?q=1': 200, '/c': 200, '/c?page=2': 200, '/d': 200, '/e': 200, '/f': 200}
RESULT = {}


def crawl(max_pages):
    SITE.requests.clear()
    OTHER.requests.clear()
    SITE.busy = 0
    out = subprocess.run(CMD + [SITE.url + '/', '--max-pages', str(max_pages), '--delay-ms', str(DELAY_MS)],
                         capture_output=True, text=True, timeout=90)
    assert out.returncode == 0, f'exit {out.returncode}: {out.stderr.strip()[-300:]}'
    lines = [json.loads(line) for line in out.stdout.splitlines() if line.startswith('{')]
    return lines, list(SITE.requests), list(OTHER.requests)


def path(url):
    assert url.startswith(SITE.url), url
    return url[len(SITE.url):] or '/'


CHECKS = []


def check(fn):
    CHECKS.append(fn)
    return fn


@check
def crawls_the_site():
    """prints one JSON line per page fetched, with its final status, and finds every allowed page"""
    lines, requests, other = crawl(100)
    RESULT.update(lines=lines, requests=requests, other=other)
    got = {path(line['url']): line['status'] for line in lines}
    assert len(got) == len(lines), 'a page was printed twice'
    assert got == EXPECTED, f'missing {sorted(set(EXPECTED) - set(got))}, extra {sorted(set(got) - set(EXPECTED))}, ' \
        f'statuses {[(p, s) for p, s in got.items() if EXPECTED.get(p) not in (None, s)]}'


@check
def depth_is_link_distance():
    """depth counts links from the start page (breadth first)"""
    depths = {path(line['url']): line['depth'] for line in RESULT['lines']}
    assert depths['/'] == 0 and depths['/a'] == 1 and depths['/c'] == 2 and depths['/d'] == 3 and depths['/e'] == 4 and depths['/f'] == 2, depths


@check
def reads_robots_first_with_its_agent():
    """fetches /robots.txt before anything else and identifies itself as cswork-bot"""
    requests = RESULT['requests']
    assert requests and requests[0][1] == '/robots.txt', [r[1] for r in requests[:3]]
    assert all('cswork-bot' in agent for _, _, agent in requests), {agent for _, _, agent in requests}


@check
def obeys_robots():
    """uses the cswork-bot group: /secret is off limits except /secret/public"""
    paths = [p for _, p, _ in RESULT['requests']]
    assert '/secret/hidden' not in paths and '/never' not in paths, 'fetched a disallowed page'


@check
def stays_on_the_site():
    """never requests another host, a mailto: link, or a link inside a non-HTML file"""
    other = RESULT['other']
    assert other == [], f'requested {[p for _, p, _ in other]} on another host'
    assert '/trap' not in [p for _, p, _ in RESULT['requests']], 'parsed links out of a JSON file'


@check
def fetches_each_page_once():
    """each URL is requested once (fragments dropped), except the retried /busy"""
    paths = [p for _, p, _ in RESULT['requests']]
    repeats = {p for p in paths if paths.count(p) > (2 if p == '/busy' else 1)}
    assert not repeats, f'requested more than once: {sorted(repeats)}'


@check
def waits_between_requests():
    """leaves at least delay-ms between requests, and honours Retry-After on a 429"""
    times = [t for t, _, _ in RESULT['requests']]
    gaps = [b - a for a, b in zip(times, times[1:])]
    # Timed where the site receives them, so allow a little jitter.
    assert min(gaps) >= DELAY_MS / 1000 * 0.8, f'two requests {min(gaps) * 1000:.0f} ms apart'
    busy = [t for t, p, _ in RESULT['requests'] if p == '/busy']
    assert len(busy) == 2 and busy[1] - busy[0] >= 0.95, 'retry /busy once, after the 1 s Retry-After'


@check
def stops_at_max_pages():
    """--max-pages 3 fetches three pages in breadth-first order and nothing more"""
    lines, requests, _ = crawl(3)
    assert [line['depth'] for line in lines] == [0, 1, 1], lines
    pages = [p for _, p, _ in requests if p != '/robots.txt']
    assert len(pages) == 3, f'requested {pages}'


def main():
    if not CMD:
        sys.exit('Set CMD to the command that starts your crawler, for example CMD="python3 crawler.py".')
    failed = 0
    for fn in CHECKS:
        try:
            fn()
            print(f'PASS  {fn.__doc__}')
        except Exception as e:  # an assertion, a crash or a timeout
            failed += 1
            print(f'FAIL  {fn.__doc__}\n      {type(e).__name__}: {e}')
    print(f'\n{len(CHECKS) - failed}/{len(CHECKS)} checks passed')
    sys.exit(1 if failed else 0)


if __name__ == '__main__':
    main()

#!/usr/bin/env python3
"""Acceptance test: feature flag service (https://cswork.org/projects/feature-flags).

Start your service, then run:
    BASE_URL=http://127.0.0.1:8080 python3 accept_test.py
Standard library only. Flag keys carry a random suffix, so reruns against the same server are
fine. The rollout checks are statistical with wide margins (4 standard deviations) on 600
users. Exit code 0 means every check passed.
"""
import json
import os
import random
import string
import sys
import urllib.error
import urllib.parse
import urllib.request

BASE = os.environ.get('BASE_URL', 'http://127.0.0.1:8080').rstrip('/')
RUN = ''.join(random.choices(string.ascii_lowercase, k=6))
USERS = [f'user-{i}' for i in range(600)]


def call(method, path, body=None, headers=None, raw=None):
    data = raw if raw is not None else (None if body is None else json.dumps(body).encode())
    req = urllib.request.Request(BASE + path, data=data, method=method, headers={'Content-Type': 'application/json', **(headers or {})})
    try:
        with urllib.request.urlopen(req, timeout=5) as r:
            status, head, text = r.status, r.headers, r.read()
    except urllib.error.HTTPError as e:
        status, head, text = e.code, e.headers, e.read()
    return status, head, (json.loads(text) if text.strip() else None)


def flag(name, enabled=True, rollout=0, rules=()):
    key = f'{name}-{RUN}'
    status, _, body = call('PUT', f'/flags/{key}', {'enabled': enabled, 'rollout': rollout, 'rules': list(rules)})
    assert status == 200, f'PUT /flags/{key} answered {status}: {body}'
    return key


def evaluate(key, user, **attributes):
    status, _, body = call('GET', f'/flags/{key}/evaluate?' + urllib.parse.urlencode({'user': user, **attributes}))
    assert status == 200, f'evaluate {key} for {user} answered {status}'
    return body


def on_users(key):
    return {u for u in USERS if evaluate(key, u)['on']}


CHECKS = []


def check(fn):
    CHECKS.append(fn)
    return fn


@check
def creates_and_reads():
    """PUT creates a flag at version 1; GET returns it with an ETag"""
    key = f'create-{RUN}'
    rules = [{'attribute': 'country', 'in': ['US'], 'serve': True}]
    status, head, body = call('PUT', f'/flags/{key}', {'enabled': True, 'rollout': 25, 'rules': rules})
    assert status == 200 and body['version'] == 1, (status, body)
    status, head, body = call('GET', f'/flags/{key}')
    assert status == 200 and body['rollout'] == 25 and body['rules'] == rules and body['version'] == 1, body
    assert head['ETag'].strip('"') == '1', head['ETag']


@check
def optimistic_concurrency():
    """each PUT bumps the version; If-Match with a stale version is 412 and changes nothing"""
    key = flag('version', rollout=10)
    status, _, body = call('PUT', f'/flags/{key}', {'enabled': True, 'rollout': 20}, {'If-Match': '"1"'})
    assert status == 200 and body['version'] == 2, (status, body)
    status, _, _ = call('PUT', f'/flags/{key}', {'enabled': True, 'rollout': 90}, {'If-Match': '"1"'})
    assert status == 412, f'a stale If-Match answered {status}'
    assert call('GET', f'/flags/{key}')[2]['rollout'] == 20


@check
def rejects_bad_flags():
    """400 for a missing or non-boolean enabled, a rollout outside 0-100, or a malformed rule"""
    key = f'bad-{RUN}'
    for body in ({'rollout': 5}, {'enabled': 'yes', 'rollout': 5}, {'enabled': True, 'rollout': 101},
                 {'enabled': True, 'rollout': 12.5}, {'enabled': True, 'rollout': 5, 'rules': [{'attribute': 'country', 'in': []}]},
                 {'enabled': True, 'rollout': 5, 'rules': [{'attribute': 'country', 'in': 'US', 'serve': True}]}):
        assert call('PUT', f'/flags/{key}', body)[0] == 400, body
    assert call('PUT', f'/flags/{key}', raw=b'{')[0] == 400


@check
def evaluate_errors():
    """evaluating an unknown flag is 404; without ?user= it is 400"""
    assert call('GET', f'/flags/nope-{RUN}/evaluate?user=a')[0] == 404
    key = flag('nouser', rollout=50)
    assert call('GET', f'/flags/{key}/evaluate')[0] == 400


@check
def disabled_is_off():
    """a disabled flag is off for everyone, reason "disabled", even when a rule matches"""
    key = flag('off', enabled=False, rollout=100, rules=[{'attribute': 'country', 'in': ['US'], 'serve': True}])
    body = evaluate(key, 'ada', country='US')
    assert body['on'] is False and body['reason'] == 'disabled', body


@check
def first_matching_rule_wins():
    """rules run in order and the first match serves its value, reason rule:<index>"""
    key = flag('rules', rollout=100, rules=[
        {'attribute': 'plan', 'in': ['free'], 'serve': False},
        {'attribute': 'country', 'in': ['US', 'CA'], 'serve': True},
    ])
    assert evaluate(key, 'a', plan='free', country='US') == {'flag': key, 'on': False, 'reason': 'rule:0', 'version': 1}
    body = evaluate(key, 'a', plan='pro', country='CA')
    assert body['on'] is True and body['reason'] == 'rule:1', body
    body = evaluate(key, 'a', country='FR')
    assert body['on'] is True and body['reason'] == 'rollout', body


@check
def rollout_extremes():
    """rollout 0 is off and 100 is on for every user"""
    zero, full = flag('zero', rollout=0), flag('full', rollout=100)
    for u in USERS[:50]:
        assert evaluate(zero, u)['on'] is False and evaluate(full, u)['on'] is True, u


@check
def sticky_per_user():
    """the same user always gets the same answer"""
    key = flag('sticky', rollout=50)
    first = {u: evaluate(key, u)['on'] for u in USERS[:60]}
    for _ in range(2):
        assert {u: evaluate(key, u)['on'] for u in USERS[:60]} == first


@check
def rollout_share():
    """rollout 30 turns the flag on for about 30% of users (22.5-37.5%)"""
    share = len(on_users(flag('share', rollout=30))) / len(USERS)
    assert 0.225 <= share <= 0.375, f'{share:.1%} on'


@check
def raising_rollout_keeps_users_on():
    """raising rollout from 30 to 60 keeps every user who was on, and reaches about 60%"""
    key = flag('grow', rollout=30)
    before = on_users(key)
    flag('grow', rollout=60)
    after = on_users(key)
    assert before <= after, f'{len(before - after)} users were switched off'
    assert 0.52 <= len(after) / len(USERS) <= 0.68, f'{len(after) / len(USERS):.1%} on'


@check
def flags_bucket_independently():
    """two flags at 50% pick different users: about a quarter are on in both (18-32%)"""
    a, b = on_users(flag('ind-a', rollout=50)), on_users(flag('ind-b', rollout=50))
    both = len(a & b) / len(USERS)
    assert 0.18 <= both <= 0.32, f'{both:.1%} on in both: the bucket must depend on the flag key'


@check
def deletes():
    """DELETE removes the flag"""
    key = flag('gone', rollout=50)
    assert call('DELETE', f'/flags/{key}')[0] in (200, 204)
    assert call('GET', f'/flags/{key}')[0] == 404
    assert call('GET', f'/flags/{key}/evaluate?user=a')[0] == 404


def main():
    failed = 0
    for fn in CHECKS:
        try:
            fn()
            print(f'PASS  {fn.__doc__}')
        except Exception as e:  # an assertion, or the service not answering
            failed += 1
            print(f'FAIL  {fn.__doc__}\n      {type(e).__name__}: {e}')
    print(f'\n{len(CHECKS) - failed}/{len(CHECKS)} checks passed')
    sys.exit(1 if failed else 0)


if __name__ == '__main__':
    main()

#!/usr/bin/env python3
"""Acceptance test: log search with an inverted index (https://cswork.org/projects/log-search).

Start your service, then run:
    BASE_URL=http://127.0.0.1:8080 python3 accept_test.py
Standard library only. It ingests about 3,000 generated lines, each carrying this run's own
token and service name, and compares every search with a brute-force model, so reruns against
the same server are fine. Exit code 0 means every check passed.
"""
import json
import os
import random
import re
import string
import sys
import urllib.error
import urllib.parse
import urllib.request

BASE = os.environ.get('BASE_URL', 'http://127.0.0.1:8080').rstrip('/')
RUN = 'run' + ''.join(random.choices(string.ascii_lowercase + string.digits, k=8))
LEVELS = ['debug', 'info', 'warn', 'error']
WORDS = ('timeout db connection reset user login failed cache miss disk full retry upstream payment '
         'order shipped queue lag slow query gc pause node down up ok').split()
rng = random.Random(2024)
LOGS = []  # this run's entries in ingestion order


def call(method, path, data=None):
    req = urllib.request.Request(BASE + path, data=data, method=method, headers={'Content-Type': 'application/x-ndjson'})
    try:
        with urllib.request.urlopen(req, timeout=10) as r:
            status, text = r.status, r.read()
    except urllib.error.HTTPError as e:
        status, text = e.code, e.read()
    return status, (json.loads(text) if text.strip() else None)


def ingest(entries):
    data = '\n'.join(json.dumps(e) for e in entries).encode()
    status, body = call('POST', '/logs', data)
    assert status == 200 and body['ingested'] == len(entries), (status, body)
    LOGS.extend(entries)


def search(**params):
    status, body = call('GET', '/search?' + urllib.parse.urlencode(params))
    assert status == 200, f'search {params} answered {status}: {body}'
    return body


def model(q='', level=None, service=None, low=None, high=None):
    """The brief's rules, by brute force: AND of terms, quoted or hyphenated terms as phrases."""
    tokens = lambda s: re.findall(r'[a-z0-9]+', s.lower())
    groups = [g for g in (tokens(a or b) for a, b in re.findall(r'"([^"]*)"|(\S+)', q)) if g]
    def phrase(words, g):
        return any(words[i:i + len(g)] == g for i in range(len(words) - len(g) + 1))
    hits = [(e['ts'], i, e) for i, e in enumerate(LOGS)
            if all(phrase(tokens(e['msg']), g) for g in groups)
            and (level is None or LEVELS.index(e['level']) >= LEVELS.index(level))
            and (service is None or e['service'] == service)
            and (low is None or e['ts'] >= low) and (high is None or e['ts'] < high)]
    return [e for _, _, e in sorted(hits, key=lambda h: (h[0], h[1]), reverse=True)]


def strip(items):
    return [{k: e[k] for k in ('ts', 'level', 'service', 'msg')} for e in items]


def everything(**params):
    """Walks every page of a search with ?cursor=."""
    items, cursor, pages = [], None, 0
    while True:
        body = search(**params, **({'cursor': cursor} if cursor else {}))
        items += body['items']
        cursor, pages = body['next'], pages + 1
        if not cursor:
            return body['total'], strip(items)
        assert pages < 2000, 'the cursor never ends'


def generate(n, start):
    out = []
    for i in range(n):
        words = rng.choices(WORDS, k=rng.randint(3, 9))
        if rng.random() < 0.3:
            words.insert(rng.randrange(len(words) + 1), 'connection reset')
        if rng.random() < 0.2:
            words.append(f'host-{rng.randint(1, 4)}')
        words.insert(rng.randrange(len(words) + 1), RUN)
        out.append({'ts': start + i // 2 * 10, 'level': rng.choice(LEVELS),  # pairs share a timestamp
                    'service': rng.choice([f'{RUN}-api', f'{RUN}-web', f'{RUN}-worker']),
                    'msg': ' '.join(words).capitalize() + rng.choice(['', '.', '!', ' (code=503)'])})
    return out


CHECKS = []


def check(fn):
    CHECKS.append(fn)
    return fn


@check
def ingests_batches():
    """POST /logs takes newline-delimited JSON and reports how many lines it stored"""
    start = 1_700_000_000_000
    for b in range(6):
        ingest(generate(500, start + b * 2500))


@check
def rejects_a_bad_batch_whole():
    """a batch with one invalid line is a 400 naming the line, and none of it is stored"""
    good = {'ts': 5, 'level': 'info', 'service': f'{RUN}-bad', 'msg': f'{RUN} poison'}
    for bad in ({**good, 'level': 'fatal'}, {**good, 'ts': 'x'}, {'ts': 5, 'level': 'info', 'msg': 'no service'}):
        data = (json.dumps(good) + '\n' + json.dumps(bad)).encode()
        status, body = call('POST', '/logs', data)
        assert status == 400 and body.get('line') == 2, (status, body)
    assert call('POST', '/logs', b'{"ts": 1,')[0] == 400
    assert search(q=f'{RUN} poison')['total'] == 0, 'nothing from a rejected batch may be stored'


@check
def single_terms():
    """one-word searches match whole tokens, case-insensitively"""
    for word in ('timeout', 'DISK', 'gc', 'up'):
        body = search(q=f'{RUN} {word}', limit=500)
        want = model(f'{RUN} {word}')
        assert body['total'] == len(want) and strip(body['items']) == want[:500], word
    assert search(q=f'{RUN} tim')['total'] == 0, 'a prefix is not a token'


@check
def terms_are_anded():
    """several terms must all be present"""
    for q in ('timeout db', 'user login failed', 'cache miss slow'):
        assert everything(q=f'{RUN} {q}', limit=100) == (len(model(f'{RUN} {q}')), model(f'{RUN} {q}')), q


@check
def phrases():
    """a quoted phrase, or a hyphenated word, matches consecutive tokens only"""
    for q in ('"connection reset"', '"reset connection"', 'host-3', '"code 503"'):
        want = model(f'{RUN} {q}')
        assert everything(q=f'{RUN} {q}', limit=200) == (len(want), want), q
    assert len(model(f'{RUN} "connection reset"')) < len(model(f'{RUN} connection reset')), 'the data must tell them apart'


@check
def filters():
    """level is a minimum, service is exact, from is inclusive and to exclusive"""
    lo, hi = LOGS[700]['ts'], LOGS[2300]['ts']
    cases = [dict(level='warn'), dict(level='error', service=f'{RUN}-api'), dict(low=lo, high=hi), dict(q=f'{RUN} retry', level='info', low=lo)]
    for case in cases:
        params = {'q': case.get('q', RUN), 'limit': 500}
        for key, name in (('level', 'level'), ('service', 'service'), ('low', 'from'), ('high', 'to')):
            if key in case:
                params[name] = case[key]
        want = model(**{'q': RUN, **case})
        assert everything(**params) == (len(want), want), case


@check
def newest_first_with_cursor():
    """results are newest first (same timestamp: last ingested first) and the cursor walks them all"""
    want = model(f'{RUN} db')
    total, got = everything(q=f'{RUN} db', limit=7)
    assert total == len(want) and got == want


@check
def rejects_bad_parameters():
    """400 for a limit outside 1-500, an unknown level or a non-numeric from"""
    for params in ({'limit': 0}, {'limit': 501}, {'level': 'fatal'}, {'from': 'yesterday'}):
        assert call('GET', '/search?' + urllib.parse.urlencode({'q': RUN, **params}))[0] == 400, params


def main():
    failed = 0
    for fn in CHECKS:
        try:
            fn()
            print(f'PASS  {fn.__doc__}')
        except Exception as e:  # an assertion, or the service not answering
            failed += 1
            print(f'FAIL  {fn.__doc__}\n      {type(e).__name__}: {e}')
    print(f'\n{len(CHECKS) - failed}/{len(CHECKS)} checks passed')
    sys.exit(1 if failed else 0)


if __name__ == '__main__':
    main()

#!/usr/bin/env python3
"""Acceptance test: mini Redis speaking RESP (https://cswork.org/projects/mini-redis).

Start your server, then run:
    BASE_URL=tcp://127.0.0.1:6379 python3 accept_test.py
Standard library only (raw sockets). Keys carry a random prefix, so reruns against the same
server are fine. Exit code 0 means every check passed.
"""
import os
import random
import socket
import string
import sys
import threading
import time
from urllib.parse import urlsplit

ADDRESS = urlsplit(os.environ.get('BASE_URL', 'tcp://127.0.0.1:6379'))
RUN = ''.join(random.choices(string.ascii_lowercase, k=6))


def encode(*args):
    parts = [a if isinstance(a, bytes) else str(a).encode() for a in args]
    return b'*%d\r\n' % len(parts) + b''.join(b'$%d\r\n%s\r\n' % (len(p), p) for p in parts)


class Client:
    def __init__(self):
        self.sock = socket.create_connection((ADDRESS.hostname, ADDRESS.port or 6379), timeout=5)
        self.file = self.sock.makefile('rb')

    def reply(self):
        line = self.file.readline()
        assert line.endswith(b'\r\n'), f'reply {line!r} does not end with CRLF'
        kind, rest = line[:1], line[1:-2]
        if kind == b'+':
            return rest.decode()
        if kind == b'-':
            return Exception(rest.decode())
        if kind == b':':
            return int(rest)
        if kind == b'$':
            if rest == b'-1':
                return None
            data = self.file.read(int(rest) + 2)
            assert data.endswith(b'\r\n'), 'bulk string must end with CRLF'
            return data[:-2]
        if kind == b'*':
            return [self.reply() for _ in range(int(rest))]
        raise AssertionError(f'unknown reply type {line!r}')

    def __call__(self, *args):
        self.sock.sendall(encode(*args))
        return self.reply()

    def close(self):
        self.sock.close()


def key(name):
    return f'{RUN}:{name}'


def is_error(value):
    return isinstance(value, Exception) and str(value).startswith('ERR')


CHECKS = []


def check(fn):
    CHECKS.append(fn)
    return fn


@check
def ping_and_echo():
    """PING answers +PONG (or echoes its argument); ECHO returns a bulk string"""
    c = Client()
    assert c('PING') == 'PONG'
    assert c('PING', 'hi') == b'hi'
    assert c('ECHO', 'hello world') == b'hello world'
    assert c('ping') == 'PONG', 'command names are case-insensitive'


@check
def set_get_del_exists():
    """SET/GET/DEL/EXISTS, with a nil bulk string for a missing key"""
    c = Client()
    assert c('GET', key('nope')) is None
    assert c('SET', key('a'), 'one') == 'OK'
    assert c('GET', key('a')) == b'one'
    assert c('SET', key('b'), 'two') == 'OK'
    assert c('EXISTS', key('a'), key('b'), key('nope'), key('a')) == 3
    assert c('DEL', key('a'), key('b'), key('nope')) == 2
    assert c('GET', key('a')) is None


@check
def binary_safe_values():
    """values are binary safe: CRLF, NUL and 1 MB values come back intact"""
    c = Client()
    tricky = b'line1\r\nline2\x00\xff\r\n'
    assert c('SET', key('bin'), tricky) == 'OK' and c('GET', key('bin')) == tricky
    big = bytes(random.getrandbits(8) for _ in range(1 << 20))
    assert c('SET', key('big'), big) == 'OK' and c('GET', key('big')) == big


@check
def set_options():
    """SET ... NX and XX set only when the key is missing or present; otherwise a nil reply"""
    c = Client()
    assert c('SET', key('nx'), '1', 'NX') == 'OK'
    assert c('SET', key('nx'), '2', 'NX') is None and c('GET', key('nx')) == b'1'
    assert c('SET', key('xx'), '1', 'XX') is None and c('GET', key('xx')) is None
    assert c('SET', key('nx'), '3', 'xx') == 'OK' and c('GET', key('nx')) == b'3'


@check
def expiry():
    """SET PX/EX, EXPIRE and TTL: -2 missing, -1 no expiry, seconds left otherwise"""
    c = Client()
    assert c('SET', key('px'), 'v', 'PX', 300) == 'OK'
    assert c('GET', key('px')) == b'v'
    c('SET', key('ex'), 'v', 'EX', 100)
    assert c('TTL', key('ex')) in (99, 100)
    c('SET', key('plain'), 'v')
    assert c('TTL', key('plain')) == -1 and c('TTL', key('nope')) == -2
    assert c('EXPIRE', key('plain'), 1) == 1 and c('EXPIRE', key('nope'), 1) == 0
    time.sleep(0.45)
    assert c('GET', key('px')) is None and c('EXISTS', key('px')) == 0
    c('SET', key('ex'), 'w')
    assert c('TTL', key('ex')) == -1, 'a plain SET clears the expiry'
    time.sleep(0.7)
    assert c('GET', key('plain')) is None and c('TTL', key('plain')) == -2


@check
def incr():
    """INCR counts from 0, and refuses a value that is not an integer"""
    c = Client()
    assert c('INCR', key('n')) == 1 and c('INCR', key('n')) == 2
    c('SET', key('n'), '41')
    assert c('INCR', key('n')) == 42 and c('GET', key('n')) == b'42'
    c('SET', key('word'), 'abc')
    assert is_error(c('INCR', key('word')))
    c('SET', key('max'), str(2 ** 63 - 1))
    assert is_error(c('INCR', key('max'))), 'INCR past a signed 64-bit integer must fail'


@check
def errors_keep_the_connection():
    """an unknown command or a wrong argument count is an -ERR reply, and the connection keeps working"""
    c = Client()
    assert is_error(c('FLY', 'away'))
    assert is_error(c('GET'))
    assert is_error(c('SET', key('x')))
    assert is_error(c('SET', key('x'), 'v', 'PX', 'soon'))
    assert c('PING') == 'PONG'


@check
def pipelining():
    """100 commands sent in one write get 100 replies in order"""
    c = Client()
    batch = b''.join(encode('SET', key(f'p{i}'), i) + encode('GET', key(f'p{i}')) for i in range(50))
    c.sock.sendall(batch)
    replies = [c.reply() for _ in range(100)]
    assert replies == [r for i in range(50) for r in ('OK', str(i).encode())]


@check
def split_frames():
    """a command that arrives a few bytes at a time is still parsed"""
    c = Client()
    frame = encode('SET', key('slow'), 'drip')
    for i in range(0, len(frame), 3):
        c.sock.sendall(frame[i:i + 3])
        time.sleep(0.005)
    assert c.reply() == 'OK' and c('GET', key('slow')) == b'drip'


@check
def concurrent_clients():
    """20 clients each INCR one key 100 times: the result is 2000"""
    def worker():
        c = Client()
        for _ in range(100):
            c('INCR', key('shared'))
        c.close()

    threads = [threading.Thread(target=worker) for _ in range(20)]
    for t in threads:
        t.start()
    for t in threads:
        t.join()
    assert Client()('GET', key('shared')) == b'2000'


def main():
    failed = 0
    for fn in CHECKS:
        try:
            fn()
            print(f'PASS  {fn.__doc__}')
        except Exception as e:  # an assertion, or the server not answering
            failed += 1
            print(f'FAIL  {fn.__doc__}\n      {type(e).__name__}: {e}')
    print(f'\n{len(CHECKS) - failed}/{len(CHECKS)} checks passed')
    sys.exit(1 if failed else 0)


if __name__ == '__main__':
    main()
